  VALUES 
    (511::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'faac31d6dfa881ff7f2722fe581c76a1136a3f8c5842c5d8965782b5624388cd'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Es un excelente profe; siempre busca la manera de poder ayudar al estudiante y le gusta que le pregunten durante la clase cuando hay dudas. Hace muchas bromas para que la clase no sea tan repetitiva. Hace quizzes,tanto grupales como individuales y para la casa.Le gusta que el estudiante sea ordenado'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-17T00:00:00+00:00'::TIMESTAMPTZ, 'ebbee4db40e740adb1dbab3a3f5cb7bdc162b21c66b81645efabb7b0546ad69d'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Es un profesor amable, dinámico y siempre dispuesto a ayudar; además, brinda material para aprobar. Sin embargo, el curso requiere esfuerzo fuera de clase. Personalmente, su metodología me dificultó concentrarme, pues hace muchas bromas y se distrae fácilmente. Lo recomiendo, pero no es para todos.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-07-11T00:00:00+00:00'::TIMESTAMPTZ, 'f020df7d8fbb13f00f3a5d9e756f214f4ea4ca1e36160b5b3dc621bd8cecf86c'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Es un profesor excelente, es muy cómico y agarra mucha confianza con sus estudiantes. Aparte de explicar muy bien deja mucha práctica extra y siempre esta abierto a aclarar dudas. Muchas veces da charlas inspiracionales y trata de que entendamos las matematicas desde una perspectiva real y lógica.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2026-06-15T00:00:00+00:00'::TIMESTAMPTZ, '134c76cd2432b8bd4f25675736fe2da3a714b6cab01dbffa26bd05ee89ed29ab'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Para un estudiante de primer ingreso de Admin, 100% recomendado, es el mejor, lo único que hay que tener es convicción, sus clases son muy claras, nunca deja botado a un estudiante, los exámenes los hace pensando en el estudiante y es super llevadera su clase, demasiado claro e inteligente, el mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2026-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'cc2d6785b96e339470e354718da6f76305960e15a244631e7c47c8ad0c2a2d34'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'De los mejores profesores que tiene la escuela de matemática, verdaderamente tiene vocación y ganas de enseñar, si pueden llevar algún curso con el háganlo, no se arrepentirán, nada más ser participativos y atentos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Respetado por los estudiantes']::TEXT[], '2026-03-02T00:00:00+00:00'::TIMESTAMPTZ, '99a406edb53476a22c0daed00d629e0618215a991fc55677c570dc1194ca37d9'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Un profesor que realmente tiene vocación por enseñar, algo que se aprecia mucho. Recomendado al 100%'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2026-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'b41ce807aaace5680f69eca84a430cff0fc26fbe882f06601b970025b788d432'::TEXT, ARRAY[563, 1620]::BIGINT[]),
    (511::BIGINT, 'Un gran profesor y el más guapo del TEC. Se esforzaba por enseñar y le importaba mucho que el estudiante practique constantemente. Además es muy chistoso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '61ece48c29321643dbe2575253de4553e6fd3690a849c60035b93fc537c706ed'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Muy buen profe, es gracioso, amable y explica fácil, pero califica duro'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'La participación importa']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'e245d1b386ca86bde55734ec049cb027cb77c1fca2afcabb88fd48bf0ec1af2b'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'El mejor profe de mate que he tenido, explica demasiado bien, primero da teoria y despues hacemos ejericios ademas de que es super ordenado, y si uno no entiende algo le ayuda. Ademas siempre da repaso de cosas basicas que no se han visto en el colegio, demasiadisimo buen profe y ser humano'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, 'd8145ef68f5b9ab70dee4b49483060daf9512f30a5883ec845423b1dd07f9f14'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Un profe bastante tuanis a la hora de explicar, y su retroalimentación ayuda demasiado, uno de los mejores profes sin duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-16T00:00:00+00:00'::TIMESTAMPTZ, '33a94aa0570d791502c775b092c486e411d40fb58a45be7e7a0144839be8f7ef'::TEXT, ARRAY[1620]::BIGINT[]),
    (511::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-15T00:00:00+00:00'::TIMESTAMPTZ, 'd622e2d71b42e2306760e0898e2e0ec10d2367be2d26e430f74776fb720e8744'::TEXT, ARRAY[1620]::BIGINT[]),
    (511::BIGINT, 'Es un amor de profesor, súper divertido y una materia muy sencilla, demasiado buen profe!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-20T00:00:00+00:00'::TIMESTAMPTZ, '712ccc5436dd7b48a037ca4067bd21ae1baf9aa511dfce94b3adbcc457fc62f9'::TEXT, ARRAY[1620]::BIGINT[]),
    (511::BIGINT, 'Es un buen profesor y trata de generar un buen ambiente en clase, aunque no brinda mucha seguridad a la hora de resolver dudas. Sus explicaciones se saltan muchos pasos que, si en su caso le cuesta mate, le va a costar bastante ir al día. Inscríbase en las tutorías de Éxito Académico.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Exámenes retadores']::TEXT[], '2025-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9b51a8538d36e913f9d4bdc9b332186cf1703222224d519b30ce7454585942a5'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'El profe es una teja, demasiado chistoso, se preocupa pq todos entiendan lo que está explicando. Demasiado buen profe, explica excelente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-17T00:00:00+00:00'::TIMESTAMPTZ, '5fca2de24bbb2398970d6dbd3bad940b704dea56aa4faa82d180ad214d67bde3'::TEXT, ARRAY[2439]::BIGINT[]),
    (511::BIGINT, 'Excelente profesor.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Tomaría su clase nuevamente']::TEXT[], '2025-03-01T00:00:00+00:00'::TIMESTAMPTZ, 'b6b4694938451146a51463bf1d8d40bf54de7c96214ca62a64bb91a468161a8d'::TEXT, ARRAY[605]::BIGINT[]),
    (511::BIGINT, 'Excelente profesor, explica super claro y todo lo que usted le pregunte se lo va a explicar, incluso si fue algo que se vió anteriormente. Además, es excelente ser humano. Super recomendado, la va a pasar muy bien y va a aprender bastante'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2025-02-19T00:00:00+00:00'::TIMESTAMPTZ, '3fa4c7a0dcd099ec97998238e66390366610e1f2ef4c839a60aec942e0821219'::TEXT, ARRAY[605]::BIGINT[]),
    (511::BIGINT, 'Un excelente profesor, el ayuda a los estudiantes si estos van a todas sus clases, es una persona muy comica y carismatica, nunca habia aprendido tanto mate como lo fue con este profesor, es una excelente persona y profesor, si es su primer vez en el curso, confio plenamente en que este es el mejor'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-02-13T00:00:00+00:00'::TIMESTAMPTZ, '29cf7dc4019f23c93a00c509361dfef30c8970511d4bd0bf82be449dbcf999a2'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Un cagadon de risa el profe, no se calla nunca, pasa diciendo que Profe Sigurd = Profe Guapo, pero ahí donde lo ven es buena nota. Nunca habia aprendido tanto en un curso hasta ahora, el profe se encarga de hacer que el estudiante aprenda de verdad y en general best profe ????'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'La participación importa']::TEXT[], '2025-02-01T00:00:00+00:00'::TIMESTAMPTZ, '1de01d0d22526bed5d9590f683c43c8cf227c330ea503c9201eabbaba18631ef'::TEXT, ARRAY[605]::BIGINT[]),
    (511::BIGINT, 'Si quieren aprender de verdad mate, matriculen con este profesor. Es excelente explicando la materia, donde da ejemplos súper claros para que uno entienda, y se nota que le gusta lo que hace. Es un charlatán, lo que hace que la clase se disfrute y pueda sacarle provecho al máximo. El mejor profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'a90df5c46d4539c1c6b96d08aa40f1d3e81491f0d149e72fa1177a6d0cd236c1'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Gran persona, es bastante cómico, por lo cual sus clases son muy divertidas, así mismo enseña bastante y siempre se preocupa de que todos entiendan. Deja tareas y quices difíciles, pero la verdad al final son de mucha ayuda para los exámenes, además siempre explica todo, lo recomiendo al 100%.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'dcb02834ebedf63863b578f3419c2c79e74916cac211c61f03fad0bf0670b67d'::TEXT, ARRAY[1018]::BIGINT[]),
    (511::BIGINT, 'Una joya recién adquirida del TEC, si usted quiere sacar un curso y entender bien la materia, metala con él siempre que pueda, es muy buena gente y se asegura que absolutamente todos entiendan, lo prepara muy bien para los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2024-11-16T00:00:00+00:00'::TIMESTAMPTZ, '69082c7cfd58ddef92a764245cf0dcf6ef587dd6d442a69fd409c26f04f14836'::TEXT, ARRAY[1018]::BIGINT[]),
    (511::BIGINT, 'Te amo profe sigurd'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-08T00:00:00+00:00'::TIMESTAMPTZ, 'c1cb8417101c21a0ef9eadfaba92d73e60f6e196f365dbc46dfce4e139524b89'::TEXT, ARRAY[1018]::BIGINT[]),
    (511::BIGINT, 'Es muy bueno. Se pasan geniales las clases con él, son pocas las tareas y quizes. A pesar de ello en mi experiencia, se necesita que estudies por tu cuenta con la cátedra pues al ser una materia de una complejidad un poco elevada, puedes perderte en clase. Tomaría de nuevo la clase con él.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2024-11-04T00:00:00+00:00'::TIMESTAMPTZ, '060ff04316096f8af485f2fa7aa0c1183e6dde8344f7e1fef8d1c9252802287f'::TEXT, ARRAY[1018]::BIGINT[]),
    (511::BIGINT, 'Si no tiene bases en matemáticas puede matricular con este profesor, repasa varios conocimientos los cuales ayudan mucho, explica muy bien y es fácil de seguir . Asista a clases, al final del semestre lo puede ayudar ya que para él la participación es importante.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-25T00:00:00+00:00'::TIMESTAMPTZ, '102b9e20f26066f7cac8fd06ca90913eeff079548577e38e4ddbd05550a1de29'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Excelente profesor, gran persona, sus clases son entretenidas, se preocupa en gran manera por que sus estudiantes aprendan y entiendan lo que está explicando, una de las mejores nuevas integraciones de la escuela de matemática.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '855299ae833a66340ecd835e058d3c7f3e736a0f4b953f039b7f8f9c7be3be6a'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Muy buen profesor que de verdad se preocupa de que los estudiantes aprendan de verdad. Tiene el don se saber cuando uno ocupa ayuda y en vez de quedarse de brazos cruzados siempre lo ayuda a uno. Además siempre busca actividades extra para reforzar la materia y lograr que el aprendizaje sea bueno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '902c8f386abed8befad2dd85cc0d60c3fc128e258c8d05048e0e45ad4fea9570'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Gran profesor, amable simpatico y gracioso, explica muy bien y tiene mucho material para estudiar, puede explicar muchas veces si es necesario y sus clases son buenas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'e28b78620e671c8dac8f4d781d723d29079b590ea3164a5ba17bcea2a7ab37ac'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '98f4474af08f3242288fcd9108a798299d42c826f7ed7e7e6be9638af08fde95'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Yo lo recomendaría muchísimo para repitentes. A veces se enreda un poco en las explicaciones y hace los quices algo duros, pero en general es un muy buen profe. Es muy comprensivo, ayuda un montón y es muy paciente. No hay pérdida matriculando con él, lo volvería a tener como profe sin duda'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Da crédito extra']::TEXT[], '2024-06-14T00:00:00+00:00'::TIMESTAMPTZ, '2e767030ba7823ceb68512f7b2021f4ac319334c751b1e124a0dc7a909f812ca'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Buen profesor, si tienes dudas te explica sin problema, muy considerado y con un gran carisma, hace exámenes todas las semanas y no califica con medios puntos. Se esfuerza por hacer comprender el tema y sus horas de consulta son muy útiles para resolver dudas. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-05-04T00:00:00+00:00'::TIMESTAMPTZ, '50f06cbdfaed70afd140bbba3cfb6551773d666bc5a6c9645ce17b9414649f85'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Un Profesor excelente, explica muy bien, flexible, amable, considerado, cómico, sus clases son muy buenas, eso si, he de tomar en cuenta que hace exámenes cortos, semanalmente y evalúa generosamente aunque no evalúa con puntos medios.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Da buena retroalimentación']::TEXT[], '2024-05-01T00:00:00+00:00'::TIMESTAMPTZ, '32f07018f610c2fc35fe463c083345533c1942c260c5bdfc9dee62ef3bc187bb'::TEXT, ARRAY[563]::BIGINT[]),
    (511::BIGINT, 'Uno de los mejores profesores para explicar, ayuda demasiado en clases y quieren que aprenda uno; ayuda muchisimo e intenta que se entienda la materia lo mas facil posible'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-03-07T00:00:00+00:00'::TIMESTAMPTZ, 'a6ba746917baaf6b71e8b9a19c043ea6a9df3785f4600b7a79df408cee8f09ac'::TEXT, ARRAY[563]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
